#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMihomoClient: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = MihomoClient

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> MihomoClient {
        return MihomoClient(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: MihomoClient) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MihomoClient {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: MihomoClient, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}




#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeMihomoClient_lift(_ pointer: UnsafeMutableRawPointer) throws -> MihomoClient {
    return try FfiConverterTypeMihomoClient.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeMihomoClient_lower(_ value: MihomoClient) -> UnsafeMutableRawPointer {
    return FfiConverterTypeMihomoClient.lower(value)
}




public protocol MobileCoreProtocol : AnyObject {
    
    func applySceneChange(sceneId: String, nodeId: UInt64, nowMillis: Int64) throws  -> SceneApply
    
    /**
     * 按 id 取缓存延迟：None = 未测或超过 max_age_millis（<=0 不过期）；-1 = 超时。顺序与 ids 一致。
     */
    func cachedLatencies(ids: [UInt64], nowMillis: Int64, maxAgeMillis: Int64)  -> [Int32?]
    
    /**
     * 平台把 dat 下载到 `geoSources()` 给的 path 后调用：编译该类全部用到的分类，返回编译的层数。
     */
    func compileGeo(kind: GeoKind, nowMillis: Int64) throws  -> UInt32
    
    /**
     * 编译一层规则（文本为 Clash 规则行或规则集 payload）。index 决定匹配顺序。
     */
    func compileRuleLayer(index: UInt32, name: String, kind: LayerKind, note: String, defaultPolicy: String, text: String) throws  -> RuleLayerInfo
    
    /**
     * 平台拉到规则集正文后交回：编译为对应层并热加载全部规则。
     */
    func compileRuleProvider(name: String, body: String, nowMillis: Int64) throws  -> RuleLayerInfo
    
    func deleteSubscription(id: String) throws 
    
    /**
     * 到了自动更新时间的订阅 id（后台任务：逐个拉取后 update_subscription）。
     */
    func dueSubscriptions(nowMillis: Int64)  -> [String]
    
    func failoverPolicy()  -> FailoverPolicy
    
    /**
     * 查询结果里已测速节点，用桌面端 smart_selector 打分排序后取前 limit 个（未测/过期不出现）。
     * 先按最近延迟预筛 256 个再打分，千万级库里也只对少量节点计算。
     * 场景候选：query = 地区代码（"JP"）；命令"最快节点"：query = 用户输入。
     */
    func fastestNodes(query: String, limit: UInt32, nowMillis: Int64, maxAgeMillis: Int64) throws  -> [RankedNode]
    
    func geoSources(nowMillis: Int64)  -> [GeoSource]
    
    func globalNode()  -> UInt64?
    
    func hostOverride(host: String)  -> HostOverride?
    
    /**
     * 导入并重建节点库。url 可空（剪贴板/文件导入）。
     */
    func importSubscription(name: String, url: String?, fetched: FetchedSubscription, autoUpdateHours: Int32, progress: BuildProgress?) throws  -> Subscription
    
    /**
     * 给 `zm_url_test` 的一批代理定义（JSON 数组，name = id 十六进制）。超过 512 个报错；找不到定义的 id 跳过。
     */
    func latencyTestBatch(ids: [UInt64]) throws  -> String
    
    /**
     * 重新加载 rules/ 下全部层（按文件名序），final_policy 为 MATCH 的去向（通常是场景 "other"）。
     */
    func loadRules(finalPolicy: String) throws  -> RuleStats
    
    func nodeDetail(id: UInt64) throws  -> NodeDetail
    
    func nodeIndex() throws  -> NodeIndex
    
    /**
     * offset：结果集内节点序号（不含分区头行）。
     */
    func nodeRows(token: UInt64, offset: UInt64, limit: UInt32) throws  -> NodePage
    
    /**
     * 连接轨迹里的覆写（contract §13）。改完需重载；persistent = false 不落盘。
     */
    func overrideHost(host: String, target: TraceTarget, sceneId: String?, persistent: Bool) throws 
    
    /**
     * 全局模式换出口的预览（"所有流量均经由新加坡 02。场景已暂停。"）：影响全部应用。
     */
    func previewGlobalChange(nodeId: UInt64) throws  -> ExitChange
    
    func previewSceneChange(sceneId: String, nodeId: UInt64) throws  -> ExitChange
    
    /**
     * "更新前显示更改"：不落盘。
     */
    func previewSubscriptionUpdate(id: String, fetched: FetchedSubscription) throws  -> SubscriptionDiff
    
    func queryNodes(query: String) throws  -> NodeQueryResult
    
    /**
     * 由已保存的全部订阅正文重建节点库（启动修复、批量更新后调用一次即可）。
     */
    func rebuildFromSubscriptions(progress: BuildProgress?) throws  -> BuildReport
    
    /**
     * 开发/演示：用原型生成器建库。scale=1.0 即 13,109,802 个节点。
     */
    func rebuildMockNodes(scale: Double) throws  -> BuildReport
    
    func rebuildMockNodesWithProgress(scale: Double, progress: BuildProgress) throws  -> BuildReport
    
    /**
     * 由全部订阅重建节点库，返回与旧库的差异（"+1,204 节点 −318 节点"）。
     */
    func rebuildNodes(sources: [SubscriptionSource]) throws  -> BuildReport
    
    /**
     * 同 rebuild_nodes，带进度与取消（UI 显示"正在建立索引 62%"；回调返回 false 取消，旧库保持不变）。
     */
    func rebuildNodesWithProgress(sources: [SubscriptionSource], progress: BuildProgress) throws  -> BuildReport
    
    /**
     * 平台/mihomo 测速结果写入（UI 同时直接推送，不必等这里）。
     * 在后台线程调用：新出现的节点会在这里一次性补齐行号（1310 万行全表扫描约 2 s），
     * 这样随后的 fastestNodes / scenes 在主线程上始终是毫秒级。
     */
    func recordLatencies(samples: [LatencySample]) throws 
    
    /**
     * `zm_url_test` 的返回 JSON 入延迟缓存，返回记录下的样本（供 latencyUpdates 推送）。
     */
    func recordUrlTest(resultJson: String, nowMillis: Int64) throws  -> [LatencySample]
    
    /**
     * 平台测得出口后回填（"198.51.100.7 · 美国"）。
     */
    func reportSceneExit(sceneId: String, ip: String, region: String?, testedAt: Int64) throws 
    
    /**
     * 平台对场景当前出口做健康探测（或连接失败）后上报。达到阈值且不在冷却期时，
     * 自动换到热备里最优的节点并返回动作；否则 None。
     *
     * AI 场景永不自动切换（原型 index.html 672–675：AI 出口 IP 只能在用户确认后更改；
     * 应用例外如 Claude 固定出口也不被任何自动逻辑改动）：照常计数，但恒返回 None，平台只提示。
     */
    func reportSceneProbe(sceneId: String, success: Bool, nowMillis: Int64) throws  -> SceneFailover?
    
    /**
     * 平台探测某服务后上报；只记录，不触发任何切换（AI 出口仅用户确认后更改，§14.y）。
     */
    func reportSceneService(sceneId: String, appId: String, ok: Bool, nowMillis: Int64) throws 
    
    /**
     * 平台把 trace 响应正文交回；解析出 ip 与地区代码后回填出口。返回出口 IP。
     */
    func reportSceneTrace(sceneId: String, body: String, nowMillis: Int64) throws  -> String
    
    func ruleProviders(nowMillis: Int64)  -> [RuleProvider]
    
    func ruleStats()  -> RuleStats
    
    /**
     * 嵌入式 mihomo 的运行时配置（zm_start / zm_reload 的输入）：该订阅正文 + Zephyr 设置。
     */
    func runtimeConfig(subscriptionId: String, options: RuntimeOptions) throws  -> String
    
    /**
     * 左右滑动切地区；region 为空时用当前节点所在地区。按 smart 分数排序，最多 50。
     */
    func sceneCandidates(sceneId: String, region: String?, nowMillis: Int64) throws  -> [RankedNode]
    
    /**
     * 测场景出口用的地址（Cloudflare trace，返回 ip= / loc=）。请求按域名走规则，所以选一个属于该场景、
     * 且没被设成例外的服务域名；视频与自定义场景没有可用的 trace 域名，返回 None。
     */
    func sceneExitProbe(sceneId: String) throws  -> String?
    
    /**
     * 该 host 走哪个场景（内置应用目录），用于轨迹页"场景"一栏。
     */
    func sceneForHost(host: String)  -> String?
    
    /**
     * 场景内需要探测健康的服务（按内置应用目录，有 probe 地址的）。
     */
    func sceneProbeTargets(sceneId: String) throws  -> [ProbeTarget]
    
    func scenes(nowMillis: Int64) throws  -> [Scene]
    
    func setFailoverPolicy(policy: FailoverPolicy) throws 
    
    /**
     * 全局模式出口。返回的 group 恒为 mihomo 内置 "GLOBAL"：平台在需要时先重载（节点此前不在配置里），
     * 然后**总是** selectInGroup("GLOBAL", member)。
     */
    func setGlobalNode(nodeId: UInt64) throws  -> SceneApply
    
    /**
     * 例外："Claude：US-Fixed-01"。node_id = None 删除例外。改完需重载。
     */
    func setSceneException(sceneId: String, appId: String, nodeId: UInt64?) throws 
    
    /**
     * 场景来源（引导"优选 / 简单"与场景 sheet 的来源分段）。
     * Auto：立即换到延迟缓存里最优的节点（当前地区优先，无选择时全库），返回需要平台执行的动作；
     * 已是最优或没有测速数据时返回 None。Manual / SubscriptionGroup：只记录。
     */
    func setSceneSource(sceneId: String, source: SceneSource, nowMillis: Int64) throws  -> SceneApply?
    
    func storageInfo()  -> StorageInfo
    
    /**
     * 平台拉取用的完整 URL（不出现在 Subscription.url 里）。
     */
    func subscriptionFetchUrl(id: String) throws  -> String?
    
    func subscriptions()  -> [Subscription]
    
    func subscriptionsSummary()  -> SubscriptionsSummary
    
    /**
     * 规则页第 2 层"订阅规则"：生效订阅（列表第一个，与运行配置一致）的 rules 编译进 rules/001.zr，
     * MATCH 的去向作为最终策略；没有订阅时删除该层、最终策略回到 DIRECT。随后热加载全部层。
     */
    func syncSubscriptionRules() throws 
    
    /**
     * 隧道未连接时的测速目标（契约 §14.u）：平台直接测到 server:port 的 TCP 握手时间，结果用 recordLatencies 写回。
     * 只在本进程内使用，不展示，server 不脱敏。基于 UDP 的协议（hysteria/hysteria2/hy2/tuic/wireguard/wg）无法 TCP 握手，跳过。
     * 超过 512 个报错；找不到定义的 id 跳过。
     */
    func tcpPingTargets(ids: [UInt64]) throws  -> [TcpTarget]
    
    func testRule(input: String) throws  -> RuleTrace
    
    /**
     * 有新鲜测速结果（max_age 内，含超时）的节点数；max_age ≤ 0 不限。
     */
    func testedCount(nowMillis: Int64, maxAgeMillis: Int64)  -> UInt64
    
    func updateSubscription(id: String, fetched: FetchedSubscription, progress: BuildProgress?) throws  -> SubscriptionDiff
    
}

