public struct BuildReport {
    public var total: UInt64
    public var skipped: UInt64
    public var diff: NodeDiff
    public var tookMillis: UInt64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(total: UInt64, skipped: UInt64, diff: NodeDiff, tookMillis: UInt64) {
        self.total = total
        self.skipped = skipped
        self.diff = diff
        self.tookMillis = tookMillis
    }
}



extension BuildReport: Equatable, Hashable {
    public static func ==(lhs: BuildReport, rhs: BuildReport) -> Bool {
        if lhs.total != rhs.total {
            return false
        }
        if lhs.skipped != rhs.skipped {
            return false
        }
        if lhs.diff != rhs.diff {
            return false
        }
        if lhs.tookMillis != rhs.tookMillis {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(total)
        hasher.combine(skipped)
        hasher.combine(diff)
        hasher.combine(tookMillis)
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBuildReport: FfiConverterRustBuffer {
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BuildReport {
        return
            try BuildReport(
                total: FfiConverterUInt64.read(from: &buf), 
                skipped: FfiConverterUInt64.read(from: &buf), 
                diff: FfiConverterTypeNodeDiff.read(from: &buf), 
                tookMillis: FfiConverterUInt64.read(from: &buf)
        )
    }

    public static func write(_ value: BuildReport, into buf: inout [UInt8]) {
        FfiConverterUInt64.write(value.total, into: &buf)
        FfiConverterUInt64.write(value.skipped, into: &buf)
        FfiConverterTypeNodeDiff.write(value.diff, into: &buf)
        FfiConverterUInt64.write(value.tookMillis, into: &buf)
    }
}


