    case Io(String
    )
    case Invalid(String
    )
    case Corrupt(String
    )
    case NotFound(String
    )
    case RuleInputInvalid(String
    )
    case SubscriptionInvalid(String
    )
    /**
     * contract v0.1：查询句柄已淘汰
     */
    case StaleToken(String
    )
    /**
     * contract v0.1：subscription_not_found
     */
    case SubscriptionNotFound(String
    )
    /**
     * contract scene_not_found
     */
    case SceneNotFound(String
    )
    /**
     * contract not_running：mihomo 未启动 / 控制 socket 不存在
     */
    case NotRunning(String
    )
    /**
     * 进度回调返回 false
     */
    case Cancelled
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMobileError: FfiConverterRustBuffer {
    typealias SwiftType = MobileError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MobileError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Io(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .Invalid(
            try FfiConverterString.read(from: &buf)
            )
        case 3: return .Corrupt(
            try FfiConverterString.read(from: &buf)
            )
        case 4: return .NotFound(
            try FfiConverterString.read(from: &buf)
            )
        case 5: return .RuleInputInvalid(
            try FfiConverterString.read(from: &buf)
            )
        case 6: return .SubscriptionInvalid(
            try FfiConverterString.read(from: &buf)
            )
        case 7: return .StaleToken(
            try FfiConverterString.read(from: &buf)
            )
        case 8: return .SubscriptionNotFound(
            try FfiConverterString.read(from: &buf)
            )
        case 9: return .SceneNotFound(
            try FfiConverterString.read(from: &buf)
            )
        case 10: return .NotRunning(
            try FfiConverterString.read(from: &buf)
            )
        case 11: return .Cancelled

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MobileError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Io(v1):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Invalid(v1):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Corrupt(v1):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .NotFound(v1):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .RuleInputInvalid(v1):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .SubscriptionInvalid(v1):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .StaleToken(v1):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .SubscriptionNotFound(v1):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .SceneNotFound(v1):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .NotRunning(v1):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(v1, into: &buf)
            
        
        case .Cancelled:
            writeInt(&buf, Int32(11))
        
        }
    }
}


